'use strict';
const shapes={arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',leaf:'<path d="M20 3C8 2 3 7 4 13c1 7 11 8 14 1 1-3 2-7 2-11Z"/><path d="M3 22c3-8 6-11 11-14"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="m9 8 6 0 2 5-5 4-5-4 2-5ZM9 8 7 5m8 3 2-3m0 8 4 1m-14-1-4 1m9 3v4"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',coffee:'<path d="M4 8h12v7a5 5 0 0 1-10 0V8m10 0h2a3 3 0 0 1 0 6h-2M3 21h16M7 2v3m5-3v3"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m2-16a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v2"/>',document:'<path d="M14 2H5v20h14V7Z"/><path d="M14 2v5h5M8 11h8m-8 4h8m-8 3h5"/>',train:'<rect x="5" y="2" width="14" height="17" rx="4"/><path d="M5 11h14M12 2v9M8 22l2-3m6 3-2-3"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="currentColor"/><circle cx="16" cy="17" r="2" fill="currentColor"/>'};
Object.assign(shapes,{down:'<path d="m7 10 5 5 5-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-14 4h3m4 0h3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2.5"/><ellipse cx="17" cy="16" rx="3" ry="2.5"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5l-2 4Zm5 4h4"/>',wave:'<path d="M2 6q3-4 6 0t6 0t8 0M2 12q3-4 6 0t6 0t8 0M2 18q3-4 6 0t6 0t8 0"/>'});
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.pin}</svg>`;
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const home=document.querySelector('#home'),workspace=document.querySelector('#workspace'),conversation=document.querySelector('#conversation'),input=document.querySelector('#request'),sheet=document.querySelector('#sheet');
conversation.className='conversation';
const state={request:'',draft:[],saved:[],hasDraft:false,kind:null,filter:'any',busy:false,version:0};
let closeTimer,toastTimer,returnFocus,undoAction;
const samples={cafe:{id:'cafe',title:'A courtyard café',description:'A coffee, a leafy corner, and some time for yourself. An outdoor option to consider.',note:'Quietness and opening hours need checking',environment:'outdoor'},coffee:{id:'coffee',title:'Community coffee',description:'A relaxed get-together for meeting a few new faces. Come for a coffee and an easy hello.',note:'Example event · organiser and date unverified',environment:'outdoor'}};
Object.assign(samples,{walk:{id:'walk',title:'A waterside walk',description:'A green path beside the water, with space to take things at your own pace.',note:'Quietness, access and conditions need checking',environment:'outdoor',image:'waterside.png'},music:{id:'music',title:'Open-air music',description:'An example outdoor music event. Check the organiser, location and date before making plans.',note:'Illustrative event · details unverified',environment:'outdoor',image:null}});
samples.cafe.image='courtyard.png';samples.coffee.image='courtyard.png';
const button=(label,action,secondary=false)=>`<button class="pill-button${secondary?' secondary':''}" data-action="${action}">${label}</button>`;
function welcome(){conversation.innerHTML=`<div class="composer-welcome"><div class="welcome-orbit">${icon('spark')}</div><h1>What would make<br>today a little better?</h1><p>A quiet corner, a new connection, or something you need to sort out. Tell me what’s on your mind.</p><div class="prompt-options"><button data-prompt="I’d like somewhere quiet to unwind.">Somewhere quiet</button><button data-prompt="I’d like to meet new people.">A little company</button><button data-prompt="I feel like doing something active.">Something active</button></div></div>`;}
welcome();
function openComposer(focus=false){clearTimeout(closeTimer);workspace.classList.remove('closing');workspace.hidden=false;home.inert=true;home.setAttribute('aria-hidden','true');home.style.visibility='hidden';document.body.style.overflow='hidden';if(focus)input.focus();}
function closeComposer(){input.blur();home.inert=false;home.removeAttribute('aria-hidden');home.style.visibility='';workspace.classList.add('closing');closeTimer=setTimeout(()=>{workspace.hidden=true;workspace.classList.remove('closing');document.body.style.overflow='';document.querySelector('.compose-submit').focus({preventScroll:true});},matchMedia('(prefers-reduced-motion: reduce)').matches?0:200);}
function echo(){return state.request?`<p class="request-echo">${safe(state.request)}</p>`:'';}
function toast(message,undo){clearTimeout(toastTimer);document.querySelector('#toast-message').textContent=message;document.querySelector('#undo').hidden=!undo;undoAction=undo;document.querySelector('#toast').classList.add('show');toastTimer=setTimeout(()=>document.querySelector('#toast').classList.remove('show'),4500);}
function openSheet(title,body){if(!sheet.open)returnFocus=document.activeElement;document.querySelector('#sheet-title').textContent=title;document.querySelector('#sheet-content').innerHTML=body;if(!sheet.open)sheet.showModal();}
sheet.addEventListener('close',()=>{if(returnFocus?.isConnected&&(document.activeElement===document.body||document.activeElement===sheet||sheet.contains(document.activeElement)))returnFocus.focus();});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();}});
function selection(){return state.draft.length?`<div class="selection-line"><span>${state.draft.length} ${state.draft.length===1?'idea':'ideas'} kept for your day</span>${button('Review my day','review')}</div>`:'';}
function renderResults(){const item=state.kind==='social'?(/music/i.test(state.request)?samples.music:samples.coffee):(/caf[eé]|coffee/i.test(state.request)?samples.cafe:samples.walk);const selected=state.draft.includes(item.id);if(state.filter==='indoor'){conversation.innerHTML=echo()+`<div class="question"><h2 class="response-title">Somewhere indoors, then.</h2><p>These sample suggestions are outdoors. Your indoor preference stays in place.</p>${button('Show all sample options','reset-filter',true)}</div>`+selection();return;}
conversation.innerHTML=echo()+`<h1 class="response-title">${state.kind==='social'?'A little company sounds good.':'A little room to breathe.'}</h1><p class="response-intro">${state.kind==='social'?'An organised gathering could be a good starting point.':'An idea for slowing down. Check the details before making it your plan.'}</p><div class="result-tools"><button class="filter-button" data-action="filters">${icon('filter')}Refine</button><span>${state.filter==='outdoor'?'Outdoors · ':''}Example suggestions</span></div><div class="result-grid"><article class="result-card">${item.image?`<div class="result-picture"><img src="./assets/${item.image}" alt="Generated illustrative scene, not a verified venue photograph"><span class="image-note">Illustrative image</span></div>`:`<div class="result-picture music-picture">${icon('music')}<span class="image-note">Example event</span></div>`}<div class="result-copy"><h3>${item.title}</h3><p>${item.description}</p><div class="result-facts">${item.note}</div><div class="result-actions"><button class="pill-button${selected?' selected':''}" data-keep="${item.id}" aria-pressed="${selected}">${icon(selected?'check':'plus')}${selected?'Kept for my day':'Keep this idea'}</button><button class="text-link" data-detail="${item.id}">Details</button></div></div></article><article class="gentle-card"><span class="symbol">${icon(state.kind==='social'?'leaf':'people')}</span><h3>${state.kind==='social'?'Prefer a little time to yourself?':'Feel like a little company?'}</h3><p>${state.kind==='social'?'We can look for somewhere you can settle in and unwind.':'A relaxed gathering is another way to spend a little time outside.'}</p><button class="pill-button secondary" data-prompt="${state.kind==='social'?'I want somewhere quiet.':'I want to meet new people.'}">${state.kind==='social'?'Find a quieter corner':'Find a gathering'}</button></article></div>`+selection();}
function question(title,text,options){conversation.innerHTML=echo()+`<div class="question"><h1 class="response-title">${title}</h1><p>${text}</p><div class="question-options">${options}</div></div>`+selection();}
async function compose(raw){const text=raw.trim();if(!text){input.focus();return;}openComposer();input.value=text;input.blur();state.request=text;state.filter='any';state.kind=null;state.busy=true;const version=++state.version;document.querySelector('.compose-submit').disabled=true;conversation.innerHTML=echo()+`<div class="loading"><h1 class="loading-title">Making a little space for your idea…</h1><div class="loading-track" aria-label="Preparing sample suggestions" role="status"><span></span></div><button class="text-link" data-action="cancel">Stop</button></div>`;document.querySelector('#workspace-scroll').scrollTop=0;await new Promise(resolve=>setTimeout(resolve,650));if(version!==state.version)return;state.busy=false;document.querySelector('.compose-submit').disabled=false;const textLower=text.toLowerCase();
if(/registration|anmeldung|paperwork|visa|permit|bureaucracy/.test(textLower)){question('Let’s find your next step.','Your paperwork belongs with your reviewed checklist.',button('Open my checklist','paperwork'));return;}
if(/directions|take me to|route to|how.*get to/.test(textLower)){question('Let’s get you there.','Your destination stays with the request. Live routes are not connected in this preview.',button('View travel options','departures'));return;}
if(/\b(no|not|avoid|without)\b|\d+\s*(km|minutes?|mins?)|\d{1,2}:\d{2}/.test(textLower)){question('Let’s keep that requirement.','These example records cannot verify every limit in your request. We’ll keep your words intact rather than substitute a different plan.',button('Edit my request','edit-request',true));return;}
if(/football|soccer|volleyball|sport|active|moving/.test(textLower)){question('A place, or people to play with?','Finding somewhere to play and finding a game to join need different suggestions.',button('A place to play','sport-place')+button('A game to join','sport-game',true));return;}
if(/quiet|unwind|relax|calm|peace|coffee|cafe|walk/.test(textLower)){state.kind='quiet';renderResults();return;}
if(/company|friends|people|meet|social|hang out|gathering|music|event/.test(textLower)){state.kind='social';renderResults();return;}
question('What would help most?','Choose a direction, or tell me a little more.',`<button class="pill-button" data-prompt="I want somewhere quiet.">A quiet place</button><button class="pill-button secondary" data-prompt="I want to meet new people.">Some company</button>`);
}
function updateCount(){const count=(state.hasDraft?state.draft:state.saved).length;const el=document.querySelector('#count');el.hidden=!count;el.textContent=count;document.querySelectorAll('#home [data-keep]').forEach(button=>{const kept=state.draft.includes(button.dataset.keep);button.classList.toggle('selected',kept);button.setAttribute('aria-pressed',String(kept));button.innerHTML=icon(kept?'check':'plus');});}
function keep(id){const old=[...state.draft];state.draft=state.draft.includes(id)?state.draft.filter(value=>value!==id):[...state.draft,id];state.hasDraft=true;updateCount();const selected=state.draft.includes(id);if(state.kind==='quiet'||state.kind==='social')renderResults();if(state.kind==='plan')renderPlan();if(sheet.open)detail(id);toast(selected?'Kept for your day':'Removed from your day',()=>{state.draft=old;updateCount();if(state.kind==='quiet'||state.kind==='social')renderResults();else if(state.kind==='plan')renderPlan();if(sheet.open)detail(id);});}
function renderPlan(saved=false){openComposer();state.kind=saved?'saved':'plan';const ids=saved?state.saved:state.draft;conversation.innerHTML=`<h1 class="response-title">${saved?'Your day, kept together.':'A little more your kind of day.'}</h1><p class="response-intro">${saved?'Your chosen ideas are saved for this preview session.':'Keep what feels right. Leave the rest.'}</p><div class="plan-list">${ids.length?ids.map((id,i)=>`<div class="plan-item"><span>${i+1}</span><div><h3>${samples[id].title}</h3><p>Timing and availability not checked</p></div>${saved?`<button class="icon-button" data-detail="${id}" aria-label="View ${samples[id].title}">${icon('arrow')}</button>`:`<button class="icon-button" data-remove="${id}" aria-label="Remove ${samples[id].title}">${icon('close')}</button>`}</div>`).join(''):'<p class="response-intro">Your day is still open. Find an idea you’d like to keep.</p>'}</div><div class="plan-actions">${saved?button('Edit my day','edit-day',true)+button('Back to Today','close-composer'):button('Find another idea','edit-request',true)+button('Save my day','save')}</div>`;}
function detail(id){const item=samples[id];openSheet(item.title,`${item.image?`<img class="detail-image" src="./assets/${item.image}" alt="Generated sample scene, not a photograph of a verified venue">`:`<div class="service-empty-illustration">${icon('music')}</div>`}<p>${item.description}</p><div class="fact"><span>Availability</span><strong>Not verified</strong></div><div class="fact"><span>Travel time</span><strong>Not calculated</strong></div><div class="fact"><span>Content</span><strong>Illustrative example</strong></div><div class="sheet-actions"><button class="pill-button${state.draft.includes(id)?' selected':''}" data-keep="${id}">${icon(state.draft.includes(id)?'check':'plus')}${state.draft.includes(id)?'Kept for my day':'Keep this idea'}</button><button class="pill-button secondary" data-about="${id}">Ask Composer about this</button></div>`);}
function link(label,action,glyph){return `<button class="service-link" data-action="${action}">${icon(glyph)}${label}${icon('arrow')}</button>`;}
function action(name){switch(name){case'places':openSheet('Places to discover',`<p>Explore the sample places, or tell Composer what you’re looking for.</p>${['walk','cafe'].map(id=>`<button class="service-link" data-detail="${id}">${icon(id==='walk'?'leaf':'coffee')}${samples[id].title}${icon('arrow')}</button>`).join('')}<div class="sheet-actions">${button('Ask Composer','edit-request',true)}</div>`);break;case'events':openSheet('Events to explore',`<p>Meet people, try something different, or make an evening of it.</p>${['coffee','music'].map(id=>`<button class="service-link" data-detail="${id}">${icon(id==='coffee'?'people':'music')}${samples[id].title}${icon('arrow')}</button>`).join('')}`);break;case'services':openSheet('Services',`<div class="service-empty-illustration">${icon('grid')}</div><p>Coming soon, as in the current app.</p>`);break;case'location':openSheet('Your starting point',`<p>Your location helps narrow down places and journeys.</p><div class="fact"><span>Location in this preview</span><strong>Not set</strong></div><p style="font-size:12px;margin-top:16px">The same layout works across cities. Sample places are fictional and have no calculated distance.</p>`);break;case'river':openSheet('River conditions',`<div class="service-empty-illustration">${icon('wave')}</div><p>Current river levels and local guidance belong here.</p><div class="fact"><span>Live readings</span><strong>Not connected</strong></div>`);break;case'today':if(!workspace.hidden)closeComposer();else window.scrollTo({top:0,behavior:'smooth'});break;case'close-composer':closeComposer();break;case'close-sheet':sheet.close();break;case'edit-request':if(sheet.open)sheet.close();input.focus();break;case'feature':detail('coffee');break;case'explore':openSheet('Follow your curiosity',link('A quieter corner','quiet','leaf')+link('A little company','company','people')+link('Something active','active','ball'));break;case'quiet':if(sheet.open)sheet.close();compose('I want somewhere quiet to unwind.');break;case'company':if(sheet.open)sheet.close();compose('I’d like to meet new people.');break;case'active':if(sheet.open)sheet.close();compose('I want to play football.');break;case'everyday':openSheet('Your everyday essentials',link('Places','explore','pin')+link('Events','feature','people')+link('Departures','departures','train')+link('Paperwork','paperwork','document')+link('Alerts and city updates','updates','sun'));break;case'paperwork':openSheet('Your paperwork',`<p>Your reviewed checklist and the next action belong here.</p><div class="fact"><span>Your case</span><strong>Not connected in this preview</strong></div>`);break;case'departures':openSheet('Getting around',`<p>Routes and departures stay connected to the places you choose.</p><div class="fact"><span>Live departures</span><strong>Not connected in this preview</strong></div>`);break;case'updates':openSheet('Your updates',`<p>Changes affecting your plans and important city updates would appear here.</p><div class="fact"><span>Live updates</span><strong>Not connected in this preview</strong></div>`);break;case'weather':openSheet('A little sunshine',`<p>21° and partly sunny.</p><p>This is sample weather for the design preview.</p>`);break;case'account':openSheet('Your space',link('My day','day','bookmark')+link('Everyday essentials','everyday','document')+link('About this design','palette','spark'));break;case'day':if(sheet.open)sheet.close();renderPlan(!state.hasDraft);break;case'review':renderPlan();break;case'edit-day':state.draft=[...state.saved];state.hasDraft=true;renderPlan();break;case'save':state.saved=[...state.draft];state.hasDraft=false;updateCount();renderPlan(true);toast('Your day is saved');break;case'cancel':state.version++;state.busy=false;document.querySelector('.compose-submit').disabled=false;question('Paused. Your request is still here.','Adjust it or press Compose when you’re ready.',button('Edit my request','edit-request',true));break;case'sport-place':question('Let’s keep the sport you chose.','This preview has no verified sports-venue records. Your requested sport will stay in the input for a real search.',button('Edit my request','edit-request',true));break;case'sport-game':question('A game you can join.','That needs a current session and an organiser welcoming new players. These sample records do not include one.',button('Edit my request','edit-request',true));break;case'filters':openSheet('Make it a better fit',`<p>Where would you like to be?</p>${[['any','Either is good'],['outdoor','Outdoors'],['indoor','Indoors']].map(([value,label])=>`<label class="filter-option"><input type="radio" name="environment" value="${value}"${state.filter===value?' checked':''}>${label}</label>`).join('')}<div class="sheet-actions">${button('Apply preference','apply-filter')}</div>`);break;case'apply-filter':state.filter=document.querySelector('input[name="environment"]:checked').value;sheet.close();renderResults();break;case'reset-filter':state.filter='any';renderResults();break;case'palette':openSheet('A familiar palette. A fresh Today.',`<p>Orange marks the action. Cyan brings the services together. Dark ink gives Composer a clear place of its own.</p><div class="palette-list">${[['Expadu orange','#FF3902'],['Expadu cyan','#05BADD'],['Soft blue','#D8F3FB'],['Ink','#211D15'],['Canvas','#F7FBFC']].map(([label,color])=>`<div class="palette-row"><i style="background:${color}"></i><span>${label}</span><code>${color}</code></div>`).join('')}</div><p style="font-size:12px;margin-top:23px;margin-bottom:0">Interactive design preview. Sample content and generated imagery. Composer responses are scripted; no live services are connected. Your draft and saved day remain in memory until this page reloads.</p>`);break;}}
input.addEventListener('input',()=>{input.style.height='27px';input.style.height=`${Math.min(95,input.scrollHeight)}px`;});
input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();compose(input.value);}if(event.key==='Escape'&&!sheet.open)closeComposer();});
document.querySelector('#compose-form').addEventListener('submit',event=>{event.preventDefault();compose(input.value);});
document.querySelector('#undo').addEventListener('click',()=>{if(undoAction)undoAction();undoAction=null;document.querySelector('#toast').classList.remove('show');});
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.action)action(target.dataset.action);else if(target.dataset.prompt)compose(target.dataset.prompt);else if(target.dataset.about){sheet.close();compose(target.dataset.about==='walk'?'I’d like a quiet walk by the water.':target.dataset.about==='cafe'?'I’d like a quiet courtyard café.':target.dataset.about==='music'?'I want an outdoor music event.':'I’d like to meet new people at a community gathering.');}else if(target.dataset.detail)detail(target.dataset.detail);else if(target.dataset.keep)keep(target.dataset.keep);else if(target.dataset.remove){state.draft=state.draft.filter(id=>id!==target.dataset.remove);state.hasDraft=true;updateCount();renderPlan();}});
